]]},["rlt_2020ghdpd2"]={["arg1"]=[[送礼条件结果]],["arg2"]=[[2020yxhd002,1]],["arg3"]=[[2020ghdjgj2]],["arg4"]=[[2020ghdtext4]],["id"]=[[rlt_2020ghdpd2]]},["rlt_2020ghdpd3"]={["arg1"]=[[送礼条件结果]],["arg2"]=[[2020yxhd003,1]],["arg3"]=[[2020ghdjgj3]],["arg4"]=[[2020ghdtext5]],["id"]=[[rlt_2020ghdpd3]]},["rlt_2020ghdpd4"]={["arg1"]=[[送礼条件结果]],["arg2"]=[[2020yxhd004,1]],["arg3"]=[[2020ghdjgj4]],["arg4"]=[[2020ghdtext6]],["id"]=[[rlt_2020ghdpd4]]},["rlt_2020ghdpd5"]={["arg1"]=[[送礼条件结果]],["arg2"]=[[2020yxhd005,1]],["arg3"]=[[2020ghdjgj5]],["arg4"]=[[2020ghdtext7]],["id"]=[[rlt_2020ghdpd5]]},["rlt_2020ghdtext01"]={["arg1"]=[[文本输出]],["arg2"]=[[缺少“咏霞”，无法挂置。]],["id"]=[[rlt_2020ghdtext01]]},["rlt_2020ghdtext02"]={["arg1"]=[[文本输出]],["arg2"]=[[缺少“凤栖”，无法挂置。]],["id"]=[[rlt_2020ghdtext02]]},["rlt_2020ghdtext03"]={["arg1"]=[[文本输出]],["arg2"]=[[缺少“公子游”，无法挂置。]],["id"]=[[rlt_2020ghdtext03]]},["rlt_2020ghdtext04"]={["arg1"]=[[文本输出]],["arg2"]=[[你想了想，还是不挂花灯了。]],["id"]=[[rlt_2020ghdtext04]]},["rlt_2020ghdtext05"]={["arg1"]=[[文本输出]],["arg2"]=[[花灯挂置太多，他人可能就没位置了，还是明日再来吧。]],["id"]=[[rlt_2020ghdtext05]]},["rlt_2020ghdtext06"]={["arg1"]=[[文本输出]],["arg2"]=[[你踏上云梯，轻轻一送便将咏霞挂于古树之上。]],["id"]=[[rlt_2020ghdtext06]]},["rlt_2020ghdtext07"]={["arg1"]=[[文本输出]],["arg2"]=[[你踏上云梯，轻轻一送便将凤栖挂于古树之上。]],["id"]=[[rlt_2020ghdtext07]]},["rlt_2020ghdtext08"]={["arg1"]=[[文本输出]],["arg2"]=[[你踏上云梯，轻轻一送便将公子游挂于古树之上。]],["id"]=[[rlt_2020ghdtext08]]},["rlt_2020ghdtext09"]={["arg1"]=[[文本输出]],["arg2"]=[[古树上已经没有位置挂花灯了。]],["id"]=[[rlt_2020ghdtext09]]},["rlt_2020ghdtext1"]={["arg1"]=[[文本输出]],["arg2"]=[[你想了想，还是不挂花灯了。]],["id"]=[[rlt_2020ghdtext1]]},["rlt_2020ghdtext10"]={["arg1"]=[[文本输出]],["arg2"]=[[随着惊鸿练裳灯被你挂上古树，一时六面翻转，灯中六幅江湖美人图明暗浮现，如相互持器对峙要较量一二。你浅浅一笑，愿：百刃皆解，取胜不败，剑鸣江湖。]],["id"]=[[rlt_2020ghdtext10]]},["rlt_2020ghdtext11"]={["arg1"]=[[文本输出]],["arg2"]=[[琼宫白玉灯内的流香倾泻，如云如瀑似要将整个琼宫湮灭，古说嫦娥应悔偷灵药，又不知子非鱼安知鱼之乐之理。你恍惚一笑，愿：浮生自在，正邪两念，何要人说。]],["id"]=[[rlt_2020ghdtext11]]},["rlt_2020ghdtext12"]={["arg1"]=[[文本输出]],["arg2"]=[[你踏上云梯，轻轻一送便将八仙云莲灯挂于古树之上。琉璃五彩，八宝如临，反将其他花灯都比得黯然失色。迎着众人艳羡的目光，你缓缓闭眼，愿：岁如华灯，生如五彩，剑指河山。]],["id"]=[[rlt_2020ghdtext12]]},["rlt_2020ghdtext2"]={["arg1"]=[[文本输出]],["arg2"]=[[花灯挂置太多，他人可能就没位置了，还是明日再来吧。]],["id"]=[[rlt_2020ghdtext2]]},["rlt_2020ghdtext3"]={["arg1"]=[[文本输出]],["arg2"]=[[缺少“双鲤鱼盏”，无法挂置。]],["id"]=[[rlt_2020ghdtext3]]},["rlt_2020ghdtext4"]={["arg1"]=[[文本输出]],["arg2"]=[[缺少“青纹墨侠灯”，无法挂置。]],["id"]=[[rlt_2020ghdtext4]]},["rlt_2020ghdtext5"]={["arg1"]=[[文本输出]],["arg2"]=[[缺少“惊鸿练裳灯”，无法挂置。]],["id"]=[[rlt_2020ghdtext5]]},["rlt_2020ghdtext6"]={["arg1"]=[[2020yxxzbjl]],["arg2"]=[[缺少“琼宫白玉灯”，无法挂置。]],["id"]=[[rlt_2020ghdtext6]]},["rlt_2020ghdtext7"]={["arg1"]=[[文本输出]],["arg2"]=[[缺少“八仙云莲灯”，无法挂置。]],["id"]=[[rlt_2020ghdtext7]]},["rlt_2020ghdtext8"]={["arg1"]=[[文本输出]],["arg2"]=[[你轻轻点足便将此灯挂于古树之上，一时微风乍起，树上红绸飞舞，双鲤鱼盏光芒点点，如在朱海波澜间翻涌，你暗暗许愿，愿：鱼跃金门，游龙在天，江湖相携。]],["id"]=[[rlt_2020ghdtext8]]},["rlt_2020ghdtext9"]={["arg1"]=[[文本输出]],["arg2"]=[[你将青纹墨侠灯挂于古树梢，只见灯心一点明随风摇曳，那灯上侠客就如起舞弄剑，生生使出一招你从未见过的武学。你微微合眼，愿：江湖快意，青山留名，不负恩仇。]],["id"]=[[rlt_2020ghdtext9]]},["rlt_2020ghdtk"]={["arg1"]=[[弹出按钮选择框]],["arg2"]=[[挂置什么花灯于古树上？]],["arg3"]=[[双鲤鱼盏,青纹墨侠灯,惊鸿练裳灯,琼宫白玉灯,八仙云莲灯]],["arg4"]=[[2020ghd1,2020ghd2,2020ghd3,2020ghd4,2020ghd5]],["id"]=[[rlt_2020ghdtk]]},["rlt_2020ghdxx"]={["arg1"]=[[弹出按钮选择框]],["arg2"]=[[挂置什么花灯于古树上？]],["arg3"]=[[咏霞,凤栖,公子游,不了]],["arg4"]=[[2020ghd01,2020ghd02,2020ghd03,2020ghdtext04]],["id"]=[[rlt_2020ghdxx]]},["rlt_2020ghdxx15"]={["arg1"]=[[弹出按钮选择框]],["arg2"]=[[挂置什么花灯于古树上？]],["arg3"]=[[咏霞,凤栖,公子游,不了]],["arg4"]=[[2020ghd01,2020ghd02,2020ghd0315,2020ghdtext04]],["id"]=[[rlt_2020ghdxx15]]},["rlt_2020gqblgjsq01"]={["arg1"]=[[开启特殊计时器]],["arg2"]=1.5,["arg3"]=[[2020gqxfjsq01]],["arg4"]=[[2020ghblgtext01;2020gqblgjsq02]],["arg5"]=[[zx3text1]],["arg6"]=2,["id"]=[[rlt_2020gqblgjsq01]]},["rlt_2020gqblgjsq02"]={["arg1"]=[[开启特殊计时器]],["arg2"]=1.5,["arg3"]=[[2020gqxfjsq02]],["arg4"]=[[2020ghblgtext02;2020gqblgjsq03]],["arg5"]=[[zx3text1]],["id"]=[[rlt_2020gqblgjsq02]]},["rlt_2020gqblgjsq03"]={["arg1"]=[[开启特殊计时器]],["arg2"]=1.5,["arg3"]=[[2020gqxfjsq03]],