]=[[2020xinchunliquanshangren1]],["arg3"]=[[2021xclqeq1;2021xclqeq2;2021xclqeq3;2021xclqeq4;2021xclqeq5;2021xclqeq6;2021xclqeq7;2021xclqeq8;2021xclqeq9;fenshenfu;dundifu;jingmai101;shuang11daoju2;jiu106;2021xinchunliquan1;xinggongsan;2020mianjufudai1;menpaicanye3;menpaicanye4;jianghuxinwulu1;2020mijicanye1;xiangmozhangfa1;xiangmozhangfa2;xiangmozhangfa3;xiangmozhangfa4;xiangmozhangfa5;shengyangjingxiecanyebox1]],["id"]=[[rlt_20xcliquanjiaoyi]]},["rlt_20xctext1"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL小贩：我们这里只能一人买一份。]],["id"]=[[rlt_20xctext1]]},["rlt_20xctext10"]={["arg1"]=[[文本输出]],["arg2"]=[[只见小贩取出豆沙酱，放入细沙糖，再将其攥成核头大的馅团。你未尝其味，只觉一股香甜，口中已经生津。]],["id"]=[[rlt_20xctext10]]},["rlt_20xctext11"]={["arg1"]=[[文本输出]],["arg2"]=[[随后他取出早已揉好的黄米面一一摆放在桌，又将豆馅团包入黄米面中，手法极其熟练，不一会儿就制出了十数个。]],["id"]=[[rlt_20xctext11]]},["rlt_20xctext12"]={["arg1"]=[[文本输出]],["arg2"]=[[小推车上摆放的蒸炉里早就被小贩铺垫上了一层梨树叶，他将粘豆包一一放入。炉火燃烧，你见白雾腾腾香气四溢，他却已将蒸好粘豆包取出，装入纸袋递给了你。]],["id"]=[[rlt_20xctext12]]},["rlt_20xctext13"]={["arg1"]=[[文本输出]],["arg2"]=[[小贩分别将莲花白和猪肉去皮洗净切成细末，用各种调料拌成饺子馅。]],["id"]=[[rlt_20xctext13]]},["rlt_20xctext14"]={["arg1"]=[[文本输出]],["arg2"]=[[又取出早已擀好的饺子皮，将饺子包成月牙状。]],["id"]=[[rlt_20xctext14]]},["rlt_20xctext15"]={["arg1"]=[[文本输出]],["arg2"]=[[等到水开后往水里加少许盐，便将饺子下锅，少时，一盘煮好的饺子和酱料便端到你面前。]],["id"]=[[rlt_20xctext15]]},["rlt_20xctext16"]={["arg1"]=[[文本输出]],["arg2"]=[[小贩打开一个大瓷罐，从中捞出一勺浓稠汤汁，你隐隐只能辩得鱼翅丝，鲍鱼丝。]],["id"]=[[rlt_20xctext16]]},["rlt_20xctext17"]={["arg1"]=[[文本输出]],["arg2"]=[[将汤汁倒入瓷锅中小火加热，加入少许料酒、食盐。]],["id"]=[[rlt_20xctext17]]},["rlt_20xctext18"]={["arg1"]=[[文本输出]],["arg2"]=[[待汤汁煮沸后，小贩用瓷碗盛出，递到你的面前。]],["id"]=[[rlt_20xctext18]]},["rlt_20xctext19"]={["arg1"]=[[文本输出]],["arg2"]=[[小贩将鲤鱼裹了一层淀粉，放入七成热的油锅之中，油锅顿时不停翻着油花。小贩随后不停用勺舀油浇在鲤鱼之上。]],["id"]=[[rlt_20xctext19]]},["rlt_20xctext2"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL小贩：这小吃，错过这家你可就吃不到了。]],["id"]=[[rlt_20xctext2]]},["rlt_20xctext20"]={["arg1"]=[[文本输出]],["arg2"]=[[待鲤鱼外皮金黄，小贩将鲤鱼捞出，盛在盘中备用。随后调出糖醋水，倒入滚烫的油锅之中。待汤汁浓稠之时，加入水淀粉收汁。]],["id"]=[[rlt_20xctext20]]},["rlt_20xctext21"]={["arg1"]=[[文本输出]],["arg2"]=[[收汁完成，小贩将糖醋浓汁浇在鲤鱼之上，撒上葱丝、姜丝、胡萝卜丝提味，随后将盘子递到你的面前。]],["id"]=[[rlt_20xctext21]]},["rlt_20xctext22"]={["arg1"]=[[文本输出]],["arg2"]=[[小贩将莲子洗净，用刀划出一个小口。将银耳切碎，同莲子一同放入砂锅之中。]],["id"]=[[rlt_20xctext22]]},["rlt_20xctext23"]={["arg1"]=[[文本输出]],["arg2"]=[[只见小贩又将山泉水倒入砂锅之中，开始小火慢炖。]],["id"]=[[rlt_20xctext23]]},["rlt_20xctext24"]={["arg1"]=[[文本输出]],["arg2"]=[[待得莲子和银耳炖的软烂，水乳交融之时，小贩将砂锅放在你的面前。]],["id"]=[[rlt_20xctext24]]},["rlt_20xctext25"]={["arg1"]=[[文本输出]],["arg2"]=[[小贩取出方形馄饨皮，用小勺舀出一勺精肉馅，放在馄饨皮上，以纯熟手法包成一个小馄饨。]],["id"]=[[rlt_20xctext25]]},["rlt_20xctext26"]={["arg1"]=[[文本输出]],["arg2"]=[[小贩以大火煮开了一锅高汤，将包好的馄饨放入锅中，不停用勺子轻轻搅动。]],["id"]=[[rlt_20xctext26]]},["rlt_20xctext27"]={["arg1"]=[[文本输出]],["arg2"]=[[待馄饨煮熟，小贩将馄饨盛入瓷碗之中，撒上葱花和香菜，放到了你的面前。]],["id"]=[[rlt_20xctext27]]},["rlt_20xctext28"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL小贩：少侠，品尝这道美食要两百钱，你似乎不够呢。]],["id"]=[[rlt_20xctext28]]},["rlt_20xctext29"]={["arg1"]=[[文本输出]],["arg2"]=[[你摆了摆手，便起身离开。]],["id"]=[[rlt_20xctext29]]},["rlt_20xctext3"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL小贩：客官稍等片刻，我这就做好。]],["id"]=[[rlt_20xctext3]]},["rlt_20xctext4"]={["arg1"]=[[文本输出]],["arg2"]=[[推车里摆放着各类年糕，小贩依次介绍，这是猪油年糕、红糖年糕、白糖年糕…正当你犹豫不决时，小贩把年糕切成了小块，好让你试吃后再做选择。]],["id"]=[[rlt_20xctext4]]},["rlt_20xctext5"]={["arg1"]=[[文本输出]],["arg2"]=[[你先吃了一块红糖年糕，入口软糯，甜而不腻，虽略有些粘牙，但一时间竟然勾起了你的食欲。]],["id"]=[[rlt_20xctext5]]},["rlt_20xctext6"]={["arg1"]=[[文本输出]],["arg2"]=[[此等美味你不愿错过，遂挑选了一些自己平日里喜好的口味，小贩熟练的将年糕装入纸袋中交给了你。]],["id"]=[[rlt_20xctext6]]},["rlt_20xctext7"]={["arg1"]=[[文本输出]],["arg2"]=[[小贩将切成丝状的肉放入锅中，倒入一些油煸炒了片刻，再将大白菜放入，予少量盐，最后淀粉入锅翻炒均匀。]],["id"]=[[rlt_20xctext7]]},["rlt_20xctext8"]={["arg1"]=[[文本输出]],["arg2"]=[[已做好的肉馅儿被小贩盛入盘中放凉。又看他再把春卷皮铺开，待馅料被包裹起来后，放入锅中煎炸，油水滚带香味一起溅出。]],["id"]=[[rlt_20xctext8]]},["rlt_20xctext9"]={["arg1"]=[[文本输出]],["arg2"]=[[小贩不急不缓的将春卷从锅中取出。鲜黄的春卷皮如黄金般色泽，内可见馅料，皮薄而肉美。不一会阵阵香味飘在空中，小贩将制好的春卷包裹好后交给你了。]],["id"]=[[rlt_20xctext9]]},["rlt_20xctk1"]={["arg1"]=[[弹出选项框]],["arg2"]=[[YEL小贩：这位客官可是要尝尝这年糕？现只需两百钱便可买上一份。]],["arg3"]=[[是]],["arg4"]=[[否]],["arg5"]=[[20xcjsq1;20xctext3;xckcmoney]],["