rlt_znq3mjhr1"]={["arg1"]=[[换人]],["arg2"]=[[znq3hdnpc1]],["arg3"]=[[znq3hdnpc4]],["id"]=[[rlt_znq3mjhr1]]},["rlt_znq3mjhr2"]={["arg1"]=[[换人]],["arg2"]=[[znq3hdnpc2]],["arg3"]=[[znq3hdnpc3]],["id"]=[[rlt_znq3mjhr2]]},["rlt_znq3mjhr3"]={["arg1"]=[[换人]],["arg2"]=[[znq3zgsxmm1]],["arg3"]=[[znq3zgsxmm2]],["id"]=[[rlt_znq3mjhr3]]},["rlt_znq3mjhr4"]={["arg1"]=[[换人]],["arg2"]=[[znq3hdnpc4]],["arg3"]=[[znq3hdnpc2]],["id"]=[[rlt_znq3mjhr4]]},["rlt_znq3mjjgj1"]={["arg1"]=[[结果集]],["arg2"]=[[znq3mjfbgs1;znq3mjbj1;znq3mjhr1]],["id"]=[[rlt_znq3mjjgj1]]},["rlt_znq3mjjgj2"]={["arg1"]=[[结果集]],["arg2"]=[[znq3mjtext5]],["id"]=[[rlt_znq3mjjgj2]]},["rlt_znq3mjtext1"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL荀无悔：哦？赵兄......莫不是忘了？]],["id"]=[[rlt_znq3mjtext1]]},["rlt_znq3mjtext10"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL荀无悔：所谓人事无常呐，若有来日必当和赵兄把酒言欢。]],["id"]=[[rlt_znq3mjtext10]]},["rlt_znq3mjtext11"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL荀无悔：悲痛之余，我如何也想不明白，这手稿怎会到了王树达的手中。]],["id"]=[[rlt_znq3mjtext11]]},["rlt_znq3mjtext12"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL荀无悔：平儿这孩子因为齐儿的事情变得戾气甚重，这可怎么办啊。]],["id"]=[[rlt_znq3mjtext12]]},["rlt_znq3mjtext13"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL荀无悔：不知下次和赵兄见面又是何时？]],["id"]=[[rlt_znq3mjtext13]]},["rlt_znq3mjtext14"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL荀无悔：齐儿平日顽劣，但天资聪颖，若非......日后必成大器。]],["id"]=[[rlt_znq3mjtext14]]},["rlt_znq3mjtext15"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL荀无悔：江湖人眼中的赵兄在下不得而知，但昔年庐中相约，赵兄仅以五年为期，就不怕我有意拖延，不曾交出此书？]],["id"]=[[rlt_znq3mjtext15]]},["rlt_znq3mjtext16"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL荀无悔：在下从未介怀赵兄的身份，赵兄又何须顾忌他人眼光。]],["id"]=[[rlt_znq3mjtext16]]},["rlt_znq3mjtext17"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL荀无悔：幽冥如何？江湖如何？在下既未身处江湖，亦非什么门派中人，有何干系。]],["id"]=[[rlt_znq3mjtext17]]},["rlt_znq3mjtext18"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL荀无悔：你并非我要找的人又为何要送我东西呢？]],["id"]=[[rlt_znq3mjtext18]]},["rlt_znq3mjtext2"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL荀无悔：江湖人眼中的赵兄在下不得而知，但昔年庐中相约，赵兄仅以五年为期，就不怕我有意拖延，不曾交出此书？]],["id"]=[[rlt_znq3mjtext2]]},["rlt_znq3mjtext3"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL荀无悔：在下从未介怀赵兄的身份，赵兄又何须顾