[[rlt_zx3text17]]},["rlt_zx3text18"]={["arg1"]=[[文本输出]],["arg2"]=[[起锅，将兔肉倒入盘子中，其上撒上厚厚的葱花，将锅中残余的热油统统浇在兔肉上。]],["id"]=[[rlt_zx3text18]]},["rlt_zx3text19"]={["arg1"]=[[文本输出]],["arg2"]=[[小贩将香气四溢的葱泼兔递到你的面前。]],["id"]=[[rlt_zx3text19]]},["rlt_zx3text2"]={["arg1"]=[[文本输出]],["arg2"]=[[小贩将大米倒入石磨中，一圈一圈的转动石磨，一股乳白的浆汁若清泉般流出来。]],["arg3"]=[[石磨肠粉]],["id"]=[[rlt_zx3text2]]},["rlt_zx3text20"]={["arg1"]=[[文本输出]],["arg2"]=[[小贩取二两羊肉，双手持刀将羊肉细细剁碎，将剁好羊肉包在面团中。]],["arg3"]=[[割肉胡饼]],["id"]=[[rlt_zx3text20]]},["rlt_zx3text21"]={["arg1"]=[[文本输出]],["arg2"]=[[将面团擀成饼状，单面抹油，撒上一层白芝麻。]],["id"]=[[rlt_zx3text21]]},["rlt_zx3text22"]={["arg1"]=[[文本输出]],["arg2"]=[[将面团贴在烤箱壁上烘烤。]],["id"]=[[rlt_zx3text22]]},["rlt_zx3text23"]={["arg1"]=[[文本输出]],["arg2"]=[[小贩看胡饼两面已是金黄，取出胡饼，用纸包好递到你的面前。]],["id"]=[[rlt_zx3text23]]},["rlt_zx3text24"]={["arg1"]=[[文本输出]],["arg2"]=[[小贩打开一个大瓷罐，从中捞出一勺浓稠汤汁，你隐隐只能辩得鱼翅丝，鲍鱼丝。]],["arg3"]=[[金丝翅肚羹]],["id"]=[[rlt_zx3text24]]},["rlt_zx3text25"]={["arg1"]=[[文本输出]],["arg2"]=[[将汤汁倒入瓷锅中小火加热，加入少许料酒、食盐。]],["id"]=[[rlt_zx3text25]]},["rlt_zx3text26"]={["arg1"]=[[文本输出]],["arg2"]=[[带汤汁煮沸后，小贩用瓷碗盛出，递到你的面前。]],["id"]=[[rlt_zx3text26]]},["rlt_zx3text27"]={["arg1"]=[[文本输出]],["arg2"]=[[小贩打开一个酒缸，浓浓的酒香让你不禁舔了舔舌头，从这酒缸中舀出几只小河蟹。]],["arg3"]=[[酒蟹]],["id"]=[[rlt_zx3text27]]},["rlt_zx3text28"]={["arg1"]=[[文本输出]],["arg2"]=[[将这些小河蟹全都放入一个蒸笼里，蒸制片刻，直到有淡淡清香飘出。]],["id"]=[[rlt_zx3text28]]},["rlt_zx3text29"]={["arg1"]=[[文本输出]],["arg2"]=[[小贩从蒸笼里取出螃蟹，递到你的面前。]],["id"]=[[rlt_zx3text29]]},["rlt_zx3text3"]={["arg1"]=[[文本输出]],["arg2"]=[[小贩拿起米浆倒入蒸箱中，便不再管它，转身拿出一个白瓷碗，双手纷飞向碗中倒入各种酱料。]],["id"]=[[rlt_zx3text3]]},["rlt_zx3text30"]={["arg1"]=[[文本输出]],["arg2"]=[[小贩取出一碗米浆，在米浆中加入小小一块面筋。]],["arg3"]=[[脆筋巴子]],["id"]=[[rlt_zx3text30]]},["rlt_zx3text31"]={["arg1"]=[[文本输出]],["arg2"]=[[小贩又向米浆倒入事先拌好的五香粉，与花生黄豆。]],["id"]=[[rlt_zx3text31]]},["rlt_zx3text32"]={["arg1"]=[[文本输出]],["arg2"]=[[将拌好的米浆，倒入热好的油锅中煎炸。]],["id"]=[[rlt_zx3text32]]},["rlt_zx3text33"]={["arg1"]=[[文本输出]],["arg2"]=[[待香气散出，小贩夹出炸至金黄的面饼，有荷叶包好，递到你的面前。]],["id"]=[[rlt_zx3text33]]},["rlt_zx3text34"]={["arg1"]=[[文本输出]],["arg2"]=[[小贩取出一块浸泡水中的乌栗豆腐，用清水洗净。]],["arg3"]=[[乌栗豆腐]],["id"]=[[rlt_zx3text34]]},["rlt_zx3text35"]={["arg1"]=[[文本输出]],["arg2"]=[[小贩手持快刀将乌栗豆腐切成小块，与姜丝、蒜瓣一起倒入铁锅中。]],["id"]=[[rlt_zx3text35]]},["rlt_zx3text36"]={["arg1"]=[[文本输出]],["arg2"]=[[小贩翻炒数次，又倒入少许酱料，焖至片刻。]],["id"]=[[rlt_zx3text36]]},["rlt_zx3text37"]={["arg1"]=[[文本输出]],["arg2"]=[[小贩将锅中的乌栗豆腐盛出，递到你的面前。]],["id"]=[[rlt_zx3text37]]},["rlt_zx3text38"]={["arg1"]=[[文本输出]],["arg2"]=[[小贩剁了少许蒜末倒入锅中爆炒，待香气溢出，倒入提前熬制的高汤。]],["arg3"]=[[米粉羹]],["id"]=[[rlt_zx3text38]]},["rlt_zx3text39"]={["arg1"]=[[文本输出]],["arg2"]=[[将提前准备好的米粉、山笋等山货倒入锅中熬制。]],["id"]=[[rlt_zx3text39]]},["rlt_zx3text4"]={["arg1"]=[[文本输出]],["arg2"]=[[小贩刚将酱料调好，便见整箱冒出滚滚白气，小贩拿出蒸好的肠粉，倒上刚刚调好酱料，便将肠粉交给你。]],["id"]=[[rlt_zx3text4]]},["rlt_zx3text40"]={["arg1"]=[[文本输出]],["arg2"]=[[等待片刻，鲜美的米粉羹便已熬好，盛出趁热递到你的面前。]],["id"]=[[rlt_zx3text40]]},["rlt_zx3text41"]={["arg1"]=[[文本输出]],["arg2"]=[[小贩拿出一根已经塞满糯米的藕段，放入盛有大枣、红糖的大锅中蒸煮。]],["arg3"]=[[江米灌藕]],["id"]=[[rlt_zx3text41]]},["rlt_zx3text42"]={["arg1"]=[[文本输出]],["arg2"]=[[蒸煮片刻后，取出煮好的藕段，切片装盘，浇上些许自家产的野蜂蜜。]],["id"]=[[rlt_zx3text42]]},["rlt_zx3text43"]={["arg1"]=[[文本输出]],["arg2"]=[[小贩便将江米灌藕端到你的面前。]],["id"]=[[rlt_zx3text43]]},["rlt_zx3text44"]={["arg1"]=[[文本输出]],["arg2"]=[[小贩将鳝鱼戳空放血备用，将鳝鱼去除内脏，切块。]],["arg3"]=[[炒鳝面]],["id"]=[[rlt_zx3text44]]},["rlt_zx3text45"]={["arg1"]=[[文本输出]],["arg2"]=[[带铁锅烧热后，放入鳝鱼翻炒，待鱼肉泛白，盛出鱼肉备用。]],["id"]=[[rlt_zx3text45]]},["rlt_zx3text46"]={["arg1"]=[[文本输出]],["arg2"]=[[将过水的面条倒入锅中，倒入鳝鱼血，翻炒数次。]],["id"]=[[rlt_zx3text46]]},["rlt_zx3text47"]={["arg1"]=[[文本输出]],["arg2"]=[[倒入切好的鳝鱼块，大火爆炒，待香味散出，起锅盛出。]],["id"]=[[rlt_zx3text47]]},["rlt_zx3text48"]={["arg1"]=[[文本输出]],["arg2"]=[[小贩将炒鳗面盛出，递到你的面前。]],["id"]=[[rlt_zx3text48]]},["rlt_zx3text49"]={["arg1"]=[[文本输出]],["arg2"]=[[小贩将青槐嫩叶捣汁和面，扯成细面条。倒入水中煮制。]],["arg3"]=[[槐叶冷淘]],["id"]=[[rlt_zx3text49]]},["rlt_zx3text5"]={["arg1"]=[[文本输出]],["arg2"]=[[小贩拿起一块揉好的面团，两边摸了些菜油，用擀面杖擀成面饼。小贩又在面饼上刷了一层菜油，小贩将面饼贴在烤炉壁上。]],["arg3"]=[[酱香烧饼]],["id"]=[[rlt_zx3text5]]},["rlt_zx3text50"]={["arg1"]=[[文本输出]],["arg2"]=[[将煮熟的面条倒入冰水中浸泡，待其色泽鲜碧，捞出用菜油浇拌。]],["id"]=[[rlt_zx3text50]]},["rlt_zx3text51"]={["arg1"]=[[文本输出]],["arg2"]=[[小贩有加了些私密佐料，便将槐叶冷淘端给你。]],["id"]=[[rlt_zx3text51]]},["rlt_zx3text52"]={["arg1"]=[[文本输出]],["arg2"]=[[小贩揭开照在重阳糕上的纱布，拿刀切了小小的一块。]],["arg3"]=[[重阳糕]],["id"]=[[rlt_zx3text52]]},["rlt_zx3text53"]={["arg1"]=[[文本输出]],["arg2"]=[[小贩将切好的重阳糕递到你的面前。]],["id"]=[[rlt_zx3text53]]},["rlt_zx3text54"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL小贩:客官稍等片刻，我这就做好。]],["id"]=[[rlt_zx3text54]]},["rlt_zx3text55"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL小贩:这小吃，错过这家你可就吃不到了。]],["id"]=[[rlt_zx3text55]]},["rlt_zx3text56"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL小贩:我们这里只能一人买一份。]],["id"]=[[rlt_zx3text56]]},["rlt_zx3text57"]={["arg1"]=[[文本输出]],["id"]=[[rlt_zx3text57]]},["rlt_zx3text58"]={["arg1"]=[[文本输出]],["id"]=[[rlt_zx3text58]]},["rlt_zx3text6"]={["arg1"]=[[文本输出]],["arg2"]=[[小贩看面饼微微泛黄，将面饼取出，在上面撒上一层肉酱，打了一个鸡蛋。又再次将面饼放入烤箱中。]],["id"]=[[rlt_zx3text6]]},["rlt_zx3text7"]={["arg1"]=[[文本输出]],["arg2"]=[[片刻后，烤箱飘出一股浓浓的肉香，面饼早已烤的两面金黄，小贩取出烧饼用荷叶包好，递到了你的面前。]],["id"]=[[rlt_zx3text7]]},["rlt_zx3text8"]={["arg1"]=[[文本输出]],["arg2"]=[[小贩打开罐子，一股恶臭飘然而出，小贩从罐子中夹出两个长毛的豆腐块。]],["arg3"]=[[臭豆腐]],["id"]=[[rlt_zx3text8]]},["rlt_zx3text9"]={["arg1"]=[[文本输出]],["arg2"]=[[小贩将豆腐块放入滚油中，随着嘶的一声，豆腐被炸成了金黄色。]],["id"]=[[rlt_zx3text9]]},["rlt_zx3timebj1"]={["arg1"]=[[玩家时间标记设置]],["arg2"]=[[石磨肠粉]],["arg3"]=1,["id"]=[[rlt_zx3timebj1]]},["rlt_zx3timebj10"]={["arg1"]=[[玩家时间标记设置]],["arg2"]=[[乌栗豆腐]],["arg3"]=1,["id"]=[[rlt_zx3timebj10]]},["rlt_zx3timebj11"]={["arg1"]=[[玩家时间标记设置]],["arg2"]=[[米粉羹]],["arg3"]=1,["id"]=[[rlt_zx3timebj11]]},["rlt_zx3timebj12"]={["arg1"]=[[玩家时间标记设置]],["arg2"]=[[江米灌藕]],["arg3"]=1,["id"]=[[rlt_zx3timebj12]]},["rlt_zx3timebj13"]={["arg1"]=[[玩家时间标记设置]],["arg2"]=[[炒鳝面]],["arg3"]=1,["id"]=[[rlt_zx3timebj13]]},["rlt_zx3timebj14"]={["arg1"]=[[玩家时间标记设置]],["arg2"]=[[槐叶冷淘]],["arg3"]=1,["id"]=[[rlt_zx3timebj14]]},["rlt_zx3timebj15"]={["arg1"]=[[玩家时间标记设置]],["arg2"]=[[重阳糕]],["arg3"]=1,["id"]=[[rlt_zx3timebj15]]},["rlt_zx3timebj2"]={["arg1"]=[[玩家时间标记设置]],["arg2